// Use Helper Classes
using System;
using VAdvantage.Utility;
using VA058Svc.HelperClass;
using VAdvantage.DataBase;
using System.Collections.Generic;

class BasicSalaryV4
{
    // Variables to hold salary calculations and relevant data
    decimal CalendarDays = 0;
    decimal BSal = 0;  // Basic salary
    decimal Gross = 0;  // Gross salary
    decimal ActualGrossAmount = 0;  // Actual gross salary (before any adjustments)
    decimal GrossSalPercent = 0;  // Percentage of gross salary used for basic salary calculation
    bool prorate = false;  // Indicates if salary needs to be prorated (due to join/leave mid-period)
    string calculationBasis = "C"; // "C" for Calendar days, "W" for Working days
    decimal WorkingDays = 0;  // Total working days for the period
    decimal SalDays = 0;  // Total days in the salary period (calendar days or working days)
    decimal absentDays = 0;  // Total absent days
    decimal unpaidLeaves = 0;  // Total unpaid leave days
    decimal paidLeaves = 0;  // Total unpaid leave days

    // Method to get the salary calculation
    public string Get(DBItem DBI)
    {
        // Fetch the gross salary amount and initialize actual gross salary
        Gross = DBI.getDBItem("Gross Salary Amount", 0);
        ActualGrossAmount = Gross;

        // Fetch basic salary from the input
        BSal = DBI.getInputValue("Pay_Value", false);

        // Initialize DateTime variables
        DateTime CalStartDate = new DateTime();
        DateTime CalEndDate = new DateTime();

        // Get Date of Joining (DOJ) and start & end dates for the current salary period
        DateTime DOJ = DBI.getDBItem("Employee Date Of Joining", "");
        DateTime startDate = new DateTime(DBI.PR_VA064_FromDate.Value.Year, DBI.PR_VA064_FromDate.Value.Month, DBI.PR_VA064_FromDate.Value.Day);
        DateTime todate = new DateTime(DBI.PR_VA064_ToDate.Value.Year, DBI.PR_VA064_ToDate.Value.Month, DBI.PR_VA064_ToDate.Value.Day);

        // Calculate Terminate Date using a custom database function
        DateTime TerminateDate = DBI.ExecuteDBFunction("VA058_GETENDOFSERVICE", DBI.C_BPartner_ID.ToString() + "," + DBI.PR_VA064_FromDate.ToString() + "," + DBI.PR_VA064_ToDate.ToString());

        // Set calendar start and end date for the period
        CalStartDate = startDate;
        CalEndDate = todate;

        // Check if the employee joined or terminated mid-period, and set prorate flag accordingly
        if ((DOJ > startDate) || (TerminateDate > startDate && TerminateDate < todate))
        {
            prorate = true;
        }

        // Calculate the total number of salary days (based on the calculation basis: calendar or working days)
        SalDays = GetDaysForCal(startDate, DBI.PR_VA064_ToDate, calculationBasis);

        // Handle prorating based on joining and termination conditions
        if (prorate)
        {
            // Joined mid-period but did not leave
            if (DOJ > startDate && TerminateDate > todate)
            {
                WorkingDays = (todate.Day - DOJ.Day) + 1;
                CalStartDate = DOJ;
            }
            // Joined before the period but terminated mid-period
            else if (DOJ <= startDate && TerminateDate < todate)
            {
                WorkingDays = (TerminateDate.Day - startDate.Day) + 1;
                CalEndDate = TerminateDate;
            }
            // Joined and terminated mid-period
            else
            {
                WorkingDays = (TerminateDate.Day - DOJ.Day) + 1;
                CalStartDate = DOJ;
                CalEndDate = TerminateDate;
            }
        }
        else
        {
            // If no prorate, calculate total working days for the period
            WorkingDays = (todate.Day - startDate.Day) + 1;
        }

        // Get the number of absent days and unpaid leave days during the period using custom DB functions
        absentDays = Util.GetValueOfDecimal(DBI.ExecuteDBFunction("VA069_GETABSENT", DBI.C_BPartner_ID.ToString() + "," + CalStartDate.ToLocalTime().ToString() + "," + CalEndDate.ToLocalTime().ToString()));
        unpaidLeaves = Util.GetValueOfDecimal(DBI.ExecuteDBFunction("VA086_GETLEAVES", DBI.C_BPartner_ID.ToString() + "," + CalStartDate.ToLocalTime().ToString() + "," + CalEndDate.ToLocalTime().ToString() + ",'UP'"));
        paidLeaves = Util.GetValueOfDecimal(DBI.ExecuteDBFunction("VA086_GETLEAVES", DBI.C_BPartner_ID.ToString() + "," + CalStartDate.ToLocalTime().ToString() + "," + CalEndDate.ToLocalTime().ToString() + ",'PA'"));

        // If there are absences or unpaid leaves, adjust the prorate flag and working days
        if (absentDays > 0 || unpaidLeaves > 0)
        {
            prorate = true;
            WorkingDays = WorkingDays - absentDays - unpaidLeaves;
        }

        // Basic Salary Calculation
        if (BSal > 0)
        {
            // If basic salary exists and prorate is true, adjust it based on working days
            if (prorate)
            {
                BSal = (BSal / SalDays) * WorkingDays;
                BSal = Math.Round(BSal);  // Round to nearest integer
            }
        }
        else
        {
            // If no basic salary is provided, calculate it based on gross salary percentage
            GrossSalPercent = Util.GetValueOfDecimal(DBI.getDBItem("GrossSalPercentage", 40));
            if (GrossSalPercent > 0)
            {
                // If prorate is true, adjust the gross salary based on working days
                if (prorate)
                {
                    Gross = (Gross / SalDays) * WorkingDays;
                }

                // Calculate basic salary as a percentage of gross salary
                BSal = (GrossSalPercent * Gross) / 100;
                BSal = Math.Round(BSal);  // Round to nearest integer
            }
        }
        decimal workingDaysWithoutPaidLeaves = WorkingDays - paidLeaves;
        // Return the results as a string (Basic Salary, Gross Salary, Actual Gross Salary)
        return BSal.ToString() + "," + Gross.ToString() + "," + ActualGrossAmount.ToString()+ "," + workingDaysWithoutPaidLeaves.ToString()+ "," + absentDays.ToString()+ "," + unpaidLeaves.ToString()+ "," + paidLeaves.ToString();
    }

    // Method to calculate the number of days between two dates based on the calculation basis (working or calendar days)
    public decimal GetDaysForCal(DateTime? JoiningDate, DateTime? EndDate, string calculationBasis)
    {
        decimal days = 0;

        // If calculation basis is 'W' (working days), exclude weekends (Saturday and Sunday)
        if (calculationBasis.Equals("W"))
        {
            while (JoiningDate <= EndDate)
            {
                // Skip weekends (Saturday and Sunday)
                if (JoiningDate.Value.DayOfWeek == DayOfWeek.Saturday || JoiningDate.Value.DayOfWeek == DayOfWeek.Sunday)
                {
                    JoiningDate = JoiningDate.Value.AddDays(1);
                    continue;
                }
                else
                {
                    days++;  // Increment days count for weekdays
                    JoiningDate = JoiningDate.Value.AddDays(1);
                }
            }
        }
        else
        {
            // If calculation basis is 'C' (calendar days), simply count all days
            days = (EndDate.Value.Day - JoiningDate.Value.Day) + 1;
        }
        return days;
    }
}

// Use Helper Classes
using System;
using VAdvantage.Utility;
using VA058Svc.HelperClass;
using VAdvantage.DataBase;

class EPF
{
    // Variables

    decimal EPFEmployee = 0, EPFEmployer = 0;
    decimal EPfCalAmount = 0;

    decimal EpfEePercent = 0;
    decimal EpfErPercent = 0;
    decimal ProvFund = 0;
    decimal BSal = 0;

    public string Get(DBItem DBI)
    {
        BSal = DBI.getDBItem("EPF Balance ASG DR", 0);
        EPfCalAmount = DBI.getDBItem("EPF Calculation Amount", 0);
        if (BSal < EPfCalAmount)
        {
            EPfCalAmount = BSal;
        }
        EpfErPercent = DBI.getDBItem("EPF Percent", 0);
        EpfEePercent = DBI.getInputValue("Percentage", false);
        if (EpfEePercent == 0)
        {
            EpfEePercent = EpfErPercent;
        }

        if (EPfCalAmount > 0)
        {
            EPFEmployee = Util.GetValueOfDecimal((EpfEePercent * EPfCalAmount) / 100);
            EPFEmployer = Util.GetValueOfDecimal((EpfErPercent * EPfCalAmount) / 100);
            ProvFund = EPFEmployee + EPFEmployer;
        }
        EPFEmployer = Math.Round(EPFEmployer);
        ProvFund = Math.Round(ProvFund);


        // Returns Results
        return EPFEmployer.ToString() + "," + ProvFund.ToString();
    }
}

// Use Helper Classes
using System;
using VAdvantage.Utility;
using VA058Svc.HelperClass;
using VAdvantage.DataBase;
class ESIV3
{
    // Variables
    decimal ESIEmployee = 0, ESIEmployer = 0;
    decimal EPfCalAmount = 0;
    decimal ESIEePercent = 0;
    decimal ESIErPercent = 0;
    decimal ESIAmt = 0;
    decimal EarnedGross = 0;
    decimal Gross = 0;
    DateTime? FromDate = null;
    DateTime? ToDate = null;
    int CountSalChange = 0;
    public string Get(DBItem DBI)
    {
        Gross = DBI.getDBItem("Gross Salary Amount", 0);
        EarnedGross = DBI.getDBItem("Gross Balance ASG DR", 0);
        //EarnedGross = Gross;
        if (Gross <= 21000)
        {
            //ESIErPercent = Util.GetValueOfDecimal(DBI.getTableValue("ESI Contribution", "ESI Contribution", "ESI Employer"));
            //ESIEePercent = Util.GetValueOfDecimal(DBI.getTableValue("ESI Contribution", "ESI Contribution", "ESI Employee"));
            ESIErPercent = DBI.getDBItem("ESI Employer Percent", 0);
            ESIEePercent = DBI.getDBItem("ESI Employee Percent", 0);
            ESIEmployer = Util.GetValueOfDecimal((EarnedGross * ESIErPercent) / 100);
            ESIEmployee = Util.GetValueOfDecimal((EarnedGross * ESIEePercent) / 100);
            ESIAmt = ESIEmployee + ESIEmployer;
        }
        else
        {
            if (DBI.PR_VA064_FromDate.Value.Month > 3 && DBI.PR_VA064_FromDate.Value.Month <= 9)

            {
                FromDate = new DateTime(DBI.PR_VA064_FromDate.Value.Year, 4, 1);
                ToDate = DBI.PR_VA064_ToDate;
            }
            else
            {
                if (DBI.PR_VA064_FromDate.Value.Month >= 1 && DBI.PR_VA064_FromDate.Value.Month <= 3)
                {
                    FromDate = new DateTime(DBI.PR_VA064_FromDate.Value.Year - 1, 10, 1);
                    ToDate = DBI.PR_VA064_ToDate;
                }
                if (DBI.PR_VA064_FromDate.Value.Month >= 10 && DBI.PR_VA064_FromDate.Value.Month <= 12)
                {
                    FromDate = new DateTime(DBI.PR_VA064_FromDate.Value.Year, 10, 1);
                    ToDate = DBI.PR_VA064_ToDate;
                }
            }
            CountSalChange = DBI.ExecuteDBFunction("VA064_CHECKSALCHANGE", DBI.Assign_ID.ToString() + "," + FromDate.ToString() + "," + ToDate.ToString() + "," + "'Gross Salary'");

            if (CountSalChange > 0)
            {
                ESIErPercent = DBI.getDBItem("ESI Employer Percent", 0);
                ESIEePercent = DBI.getDBItem("ESI Employee Percent", 0);
                ESIEmployer = Util.GetValueOfDecimal((21000 * ESIErPercent) / 100);
                ESIEmployee = Util.GetValueOfDecimal((21000 * ESIEePercent) / 100);
            }

            ESIAmt = ESIEmployee + ESIEmployer;
        }

        decimal ESI = ESIEmployer + ESIEmployee;
        return ESIEmployer.ToString() + "," + ESI.ToString();
        ESIEmployer = Math.Round(ESIEmployer);
        ESIEmployee = Math.Round(ESIEmployee);
        ESIAmt = Math.Round(ESIAmt);
        // Returns Results
        return ESIEmployer.ToString() + "," + ESIEmployee.ToString();
    }
}

