// Use Helper Classes
using System;
using VAdvantage.Utility;
using VA058Svc.HelperClass;
using VAdvantage.DataBase;

class HouseRentAllowanceV1
{
    // Variables

    decimal HRA = 0;
    decimal BSal = 0;
    decimal Gross = 0;

    string CityType = "M";
    decimal HRAPercent = 0;

    public string Get(DBItem DBI)
    {
        CityType = DBI.getDBItem("Employee City Type", "N");
        BSal = DBI.getDBItem("Basic Salary Balance ASG DR", 0);
        Gross = DBI.getDBItem("Gross Salary Amount", 0);//Get Actual Gross salary.
        if (BSal > 0)
        {
            if (CityType.Equals("M"))
            {
                HRAPercent = DBI.getDBItem("HRA Percentage Metro", 50);
            }
            if (CityType.Equals("N"))
            {
                HRAPercent = DBI.getDBItem("HRA Percentage Non-Metro", 40);
            }
            HRA = Util.GetValueOfDecimal((HRAPercent * BSal) / 100);
        }

        HRA = Math.Round(HRA);

        // Returns Results
        return HRA.ToString();
    }
}

using System;
using VAdvantage.Utility;
using VA058Svc.HelperClass;
using VAdvantage.DataBase;
using System.Collections.Generic;

// Class to calculate and return the Dearness Allowance based on certain database item values
class DearnessAllowance
{
    // Declare private fields for storing necessary values
    decimal value = 0;  // Holds the value for Dearness Allowance pay value
    decimal workingDays = 0;  // Holds the number of working days
    decimal calendarDay = 0;  // Holds the total number of days in the calendar period
    decimal DNllowance = 0;  // Holds the calculated Dearness allowance

    // Method to get the Dearness allowance based on a given database item
    public string Get(DBItem DBI)
    {
        // Retrieve the "Dearness Allowance Pay_Value" from the database item. Default is 0 if not found.
        value = DBI.getDBItem("Dearness Allowance Pay_Value", 0);

        // If the value of the Dearness allowance is greater than 0, calculate the travel allowance.
        if (value > 0)
        {
            // Retrieve the number of working days balance from the database item.
            workingDays = DBI.getDBItem("Working Day Balance ASG DR", 0);

            // Calculate the total number of calendar days by subtracting the from-date from the to-date
            calendarDay = (DBI.PR_VA064_ToDate.Value.Day - DBI.PR_VA064_FromDate.Value.Day) + 1;

            // Calculate the total allowance: (Dearness value / total calendar days) * working days
            DNllowance = Math.Round((value / calendarDay * workingDays), 2);
        }

        // Return the calculated Dearness allowance as a string
        return DNllowance.ToString();
    }
}

using System;
using VAdvantage.Utility;
using VA058Svc.HelperClass;
using VAdvantage.DataBase;
using System.Collections.Generic;

// Class to calculate and return the TravelAllowance based on certain database item values
class TravelAllowance
{
    // Declare private fields for storing necessary values
    decimal value = 0;  // Holds the value for TravelAllowance  pay value
    decimal workingDays = 0;  // Holds the number of working days
    decimal calendarDay = 0;  // Holds the total number of days in the calendar period
    decimal TAllowance = 0;  // Holds the calculated TravelAllowance 

    // Method to get the TravelAllowance based on a given database item
    public string Get(DBItem DBI)
    {
        // Retrieve the "Travel Allowance Pay_Value" from the database item. Default is 0 if not found.
        value = DBI.getDBItem("Travelling Allowance Pay_Value", 0);

        // If the value of the Travel allowance is greater than 0, calculate the travel allowance.
        if (value > 0)
        {
            // Retrieve the number of working days balance from the database item.
            workingDays = DBI.getDBItem("Working Day Balance ASG DR", 0);

            // Calculate the total number of calendar days by subtracting the from-date from the to-date
            calendarDay = (DBI.PR_VA064_ToDate.Value.Day - DBI.PR_VA064_FromDate.Value.Day) + 1;

            // Calculate the total allowance: (Travel value / total calendar days) * working days
            TAllowance = Math.Round((value / calendarDay * workingDays), 2);
        }

        // Return the calculated Travel allowance as a string
        return TAllowance.ToString();
    }
}

// Use Helper Classes
using System;
using VAdvantage.Utility;
using VA058Svc.HelperClass;
using VAdvantage.DataBase;

class SpecialAllowance
{
    // Variables

    decimal GrossBalance = 0, SpecialAllBalance = 0;
    decimal SpecialAllow = 0;


    public string Get(DBItem DBI)
    {
        GrossBalance = DBI.getDBItem("Gross Balance ASG DR", 0);
        SpecialAllBalance = DBI.getDBItem("Balance Special Allowance ASG DR", 0);

        if (GrossBalance > SpecialAllBalance)
        {
            SpecialAllow = GrossBalance - SpecialAllBalance;
        }
        //SpecialAllow = Math.Round(SpecialAllow);

        // Returns Results
        return SpecialAllow.ToString();
    }
}
